export type QzSeverity = "breaks-silently" | "degrades" | "info";
export type QzTarget = "body" | "frontmatter";

export type QzLocalizedText = { ja: string; en: string };

export type QzRule = {
  id: string;
  direction: QzDirection | "both";
  category: QzCategory;
  target: QzTarget;
  severity: QzSeverity;
  feature: QzLocalizedText;
  qiita: string | null;
  zenn: string | null;
  detect:
    | { kind: "regex"; pattern: string; flags: string }
    | { kind: "handler" };
  transform:
    | { kind: "regex-replace"; pattern: string; flags: string; replacement: string }
    | { kind: "identity" }
    | { kind: "handler" }
    | null;
  userAction: {
    prompt: QzLocalizedText;
    options: Array<{ value: string; ja: string; en: string }>;
    fallback: string;
  } | null;
  source: string | null;
};

